package gogen

import (
	"bytes"
	"fmt"
	"go/ast"
	"go/format"
	"go/parser"
	"go/token"
	"slices"
	"strconv"
	"strings"

	"github.com/sohretaga/govibe/internal/ir"
	"github.com/sohretaga/govibe/internal/sqlgen"
)

// header starts every generated file.
const header = "// Code generated by vibe build from .vibe files. DO NOT EDIT.\n\npackage main\n\n"

// Unsupported reports a construct this version of vibe build cannot
// generate yet.
type Unsupported struct {
	Pos  ir.Pos
	What string
}

func (e *Unsupported) Error() string {
	return fmt.Sprintf("%s:%d:%d: vibe build does not support %s yet", e.Pos.File, e.Pos.Line, e.Pos.Col, e.What)
}

// Generate returns the Go files of p, keyed by file name.
func Generate(p *ir.Program) (files map[string][]byte, err error) {
	g := newGen(p)
	defer func() {
		// The generator stops at the first construct it cannot generate.
		if r := recover(); r != nil {
			u, ok := r.(*Unsupported)
			if !ok {
				panic(r)
			}
			files, err = nil, u
		}
	}()
	if p.Auth != nil {
		g.unsupported(p.Auth.Pos, "auth")
	}
	for _, f := range p.Funcs {
		if f.Extern {
			g.unsupported(f.Pos, "extern fn")
		}
	}
	src := map[string]string{
		"models.go":   g.models(),
		"handlers.go": g.handlers(),
	}
	if fns := g.fns(); fns != header {
		src["fns.go"] = fns
	}
	src["queries.go"] = g.queries()
	src["main.go"] = g.main()
	files = map[string][]byte{}
	for name, body := range src {
		out, err := finish(name, body)
		if err != nil {
			return nil, err
		}
		files[name] = out
	}
	return files, nil
}

// gen holds what the generated files share.
type gen struct {
	prog   *ir.Program
	fields map[*ir.Field]string // Go name of every model field
	sql    []sqlConst
	sqlSet map[string]bool
	sites  int
	// siteFuncs holds the function of every query site.
	siteFuncs []string
}

type sqlConst struct {
	name, query, comment string
}

func newGen(p *ir.Program) *gen {
	g := &gen{prog: p, fields: map[*ir.Field]string{}, sqlSet: map[string]bool{}}
	for _, m := range p.Models {
		taken := map[string]bool{}
		for _, f := range m.Fields {
			name := pascal(f.Name)
			for taken[name] {
				name += "_"
			}
			taken[name] = true
			g.fields[f] = name
		}
	}
	return g
}

func (g *gen) unsupported(pos ir.Pos, what string) {
	panic(&Unsupported{Pos: pos, What: what})
}

// constSQL registers an SQL constant and returns its name.
func (g *gen) constSQL(name, query, comment string) string {
	if !g.sqlSet[name] {
		g.sqlSet[name] = true
		g.sql = append(g.sql, sqlConst{name, query, comment})
	}
	return name
}

// site registers the query of one query site and returns the name of the
// function that runs it.
func (g *gen) site(q *ir.QueryExpr, plan sqlgen.Plan) string {
	g.sites++
	n := strconv.Itoa(g.sites)
	c := g.constSQL("sqlQuery"+n, plan.SQL, fmt.Sprintf("is the query at %s.", where(q.Position())))
	m := q.Model.Name
	var b strings.Builder
	switch q.Result {
	case ir.Count:
		fmt.Fprintf(&b, "func runQuery%s(c *vibe.Ctx, args ...any) (int64, error) {\n\treturn vibe.Count(c, %s, args...)\n}\n", n, c)
	case ir.First:
		fmt.Fprintf(&b, "func runQuery%s(c *vibe.Ctx, args ...any) (*%s, error) {\n\treturn vibe.First(c, %s, scan%s, args...)\n}\n", n, m, c, m)
	default:
		fmt.Fprintf(&b, "func runQuery%s(c *vibe.Ctx, args ...any) ([]*%s, error) {\n\treturn vibe.All(c, %s, scan%s, args...)\n}\n", n, m, c, m)
	}
	g.siteFuncs = append(g.siteFuncs, fmt.Sprintf("// runQuery%s runs the query at %s.\n%s", n, where(q.Position()), b.String()))
	return "runQuery" + n
}

func where(p ir.Pos) string {
	return fmt.Sprintf("%s:%d:%d", p.File, p.Line, p.Col)
}

// queries returns queries.go: every SQL constant and the function of
// every query site.
func (g *gen) queries() string {
	var b strings.Builder
	b.WriteString(header)
	b.WriteString("const (\n")
	for _, s := range g.sql {
		fmt.Fprintf(&b, "\t// %s %s\n\t%s = %s\n", s.name, s.comment, s.name, strconv.Quote(s.query))
	}
	b.WriteString(")\n\n")
	b.WriteString("// queries returns every statement of the app, which the runtime prepares\n// at startup.\nfunc queries() []string {\n\treturn []string{\n")
	for _, s := range g.sql {
		fmt.Fprintf(&b, "\t\t%s,\n", s.name)
	}
	b.WriteString("\t}\n}\n")
	for _, f := range g.siteFuncs {
		b.WriteString("\n" + f)
	}
	return b.String()
}

// packages maps the package names generated code uses to import paths.
var packages = map[string]string{
	"vibe":    "vibeapp/runtime",
	"time":    "time",
	"strings": "strings",
	"errors":  "errors",
	"os":      "os",
	"sqlite":  "modernc.org/sqlite",
	"driver":  "database/sql/driver",
}

// finish adds the imports a file uses and formats it.
func finish(name, src string) ([]byte, error) {
	fset := token.NewFileSet()
	f, err := parser.ParseFile(fset, name, src, parser.SkipObjectResolution)
	if err != nil {
		return nil, fmt.Errorf("gogen: %s does not parse: %w\n%s", name, err, numbered(src))
	}
	used := map[string]bool{}
	ast.Inspect(f, func(n ast.Node) bool {
		if sel, ok := n.(*ast.SelectorExpr); ok {
			if id, ok := sel.X.(*ast.Ident); ok && packages[id.Name] != "" {
				used[id.Name] = true
			}
		}
		return true
	})
	var std, other []string
	for pkg := range used {
		path := packages[pkg]
		line := strconv.Quote(path)
		if pkg == "vibe" {
			line = "vibe " + line
		}
		if strings.Contains(path, ".") || strings.Contains(path, "/") && !strings.HasPrefix(path, "database/") {
			other = append(other, line)
		} else {
			std = append(std, line)
		}
	}
	slices.Sort(std)
	slices.Sort(other)
	var imports string
	switch {
	case len(std)+len(other) == 0:
	default:
		groups := []string{}
		if len(std) > 0 {
			groups = append(groups, "\t"+strings.Join(std, "\n\t"))
		}
		if len(other) > 0 {
			groups = append(groups, "\t"+strings.Join(other, "\n\t"))
		}
		imports = "import (\n" + strings.Join(groups, "\n\n") + "\n)\n\n"
	}
	full := strings.Replace(src, header, header+imports, 1)
	out, err := format.Source([]byte(full))
	if err != nil {
		return nil, fmt.Errorf("gogen: format %s: %w\n%s", name, err, numbered(full))
	}
	return out, nil
}

func numbered(src string) string {
	var b bytes.Buffer
	for i, line := range strings.Split(src, "\n") {
		fmt.Fprintf(&b, "%4d  %s\n", i+1, line)
	}
	return b.String()
}
